 349		\begin{definition}[The ideal Pauli register measurement]
 350			\label{def:qld-pauli-register-measurement}
 351			\lean{MIPStarRE.QPBT.pauliRegisterMeas}
 352			\leanok
 353			This measurement is not named in the source article. For a fixed Pauli
 354			basis it is the measurement of the ancillary Pauli register in that basis,
 355			assembled from the positivity and completeness of the Pauli projectors.
 356		\end{definition}
 357	
 358		\begin{lemma}[Bounded encodings lie in the decoder's image]
 359			\label{lem:qld-is-encoding-encoding-poly}
 360			\lean{MIPStarRE.QPBT.isEncoding_encodingPoly}
 361			\leanok
 362			\uses{def:low-degree-encoding, def:qld-full-field-decoder}
 363			The low-degree encoding of Definition~\ref{def:low-degree-encoding} of any
 364			Pauli register value lies in the encoding image of the full-field decoder
 365			of Definition~\ref{def:qld-full-field-decoder}.
 366		\end{lemma}
 367		\begin{proof}
 368			\leanok
 369			Decoding the encoding of a register value returns that value.
 370		\end{proof}
