 372		\begin{definition}[The encoding-supported Pauli reference measurement]
 373			\label{def:qld-encoding-pauli-measurement}
 374			\lean{MIPStarRE.QPBT.ProjectiveSetting.encodingPauliMeas}
 375			\leanok
 376			\uses{def:qld-pauli-register-measurement, def:low-degree-encoding,
 377				def:post-processing}
 378			This measurement is not named in the source article; it is the internal
 379			reference measurement underlying Equation~\eqref{eq:qld-nonencoding-mass}.
 380			For a player and a Pauli basis, measure the strategy's Pauli answer
 381			together with the ideal Pauli answer of
 382			Definition~\ref{def:qld-pauli-register-measurement} on the ancillary
 383			register, and return the low-degree encoding of the sum of the two answers.
 384			This is not the global polynomial-pair measurement whose existence
 385			Lemma~\ref{lem:qld-4-7} asserts.
 386		\end{definition}
