 388		\begin{lemma}[The reference effects are sums over encoding fibers]
 389			\label{lem:qld-encoding-pauli-effect}
 390			\lean{MIPStarRE.QPBT.ProjectiveSetting.encodingPauliMeas_effect}
 391			\leanok
 392			\uses{def:qld-encoding-pauli-measurement}
 393			The effect of the measurement of
 394			Definition~\ref{def:qld-encoding-pauli-measurement} at a polynomial is the
 395			sum of the product effects over the pairs of Pauli answers whose sum
 396			encodes that polynomial.
 397		\end{lemma}
 398		\begin{proof}
 399			\leanok
 400			This is the definition of the relabeled product measurement.
 401		\end{proof}
 402	
 403		\begin{lemma}[The reference measurement is a complete POVM]
 404			\label{lem:qld-encoding-pauli-complete}
 405			\lean{MIPStarRE.QPBT.ProjectiveSetting.encodingPauliMeas_effect_nonneg}
 406			\lean{MIPStarRE.QPBT.ProjectiveSetting.sum_encodingPauliMeas_effect_eq_one}
 407			\leanok
 408			\uses{def:qld-encoding-pauli-measurement}
 409			Every effect of the measurement of
 410			Definition~\ref{def:qld-encoding-pauli-measurement} is positive
 411			semidefinite, and the effects sum to the identity on the strategy and
 412			ancillary registers.
 413		\end{lemma}
 414		\begin{proof}
 415			\leanok
 416			Positivity and completeness are inherited from the product measurement and
 417			are preserved by relabeling of the outcomes.
 418		\end{proof}
