 420		\begin{lemma}[Exact encoding support of the reference measurement]
 421			\label{lem:qld-encoding-pauli-support}
 422			\lean{MIPStarRE.QPBT.ProjectiveSetting.encodingPauliMeas_effect_eq_zero_of_not_isEncoding}
 423			\leanok
 424			\uses{def:qld-encoding-pauli-measurement, def:qld-full-field-decoder}
 425			The effect of the measurement of
 426			Definition~\ref{def:qld-encoding-pauli-measurement} vanishes at every
 427			polynomial outside the encoding image of the full-field decoder of
 428			Definition~\ref{def:qld-full-field-decoder}. This is exact support of the
 429			auxiliary measurement; it is not a bound on the non-encoding marginal mass
 430			of Lemma~\ref{lem:qld-nonencoding-mass-bound}.
 431		\end{lemma}
 432		\begin{proof}
 433			\leanok
 434			\uses{lem:qld-encoding-pauli-effect, lem:qld-is-encoding-encoding-poly}
 435			By Lemma~\ref{lem:qld-encoding-pauli-effect} the effect is a sum over the
 436			pairs of Pauli answers whose sum encodes the given polynomial. By
 437			Lemma~\ref{lem:qld-is-encoding-encoding-poly} every such polynomial lies in
 438			the encoding image, so outside that image the index set is empty.
 439		\end{proof}
