 441		\begin{lemma}[Evaluation splits over the two Pauli answers]
 442			\label{lem:qld-encoding-pauli-eval}
 443			\lean{MIPStarRE.QPBT.ProjectiveSetting.encodingPauliMeas_postprocess_eval}
 444			\leanok
 445			\uses{def:qld-encoding-pauli-measurement, def:low-degree-encoding,
 446				def:post-processing}
 447			Evaluating the polynomial outcome of
 448			Definition~\ref{def:qld-encoding-pauli-measurement} at a point is the same
 449			as evaluating the two Pauli answers separately at that point and adding the
 450			two values.
 451		\end{lemma}
 452		\begin{proof}
 453			\leanok
 454			\uses{lem:qld-tensor-measurement-postprocess}
 455			Composing the two relabelings and moving them through the product
 456			measurement with Lemma~\ref{lem:qld-tensor-measurement-postprocess} reduces
 457			the claim to additivity of the low-degree encoding of
 458			Definition~\ref{def:low-degree-encoding} in its register argument, which
 459			holds because that encoding is a scalar product with the point.
 460		\end{proof}
 461	
 462		\begin{lemma}[The evaluated reference effects are the Pauli-answer convolution]
 463			\label{lem:qld-encoding-pauli-convolution}
 464			\lean{MIPStarRE.QPBT.ProjectiveSetting.encodingPauliMeas_eval_effect_eq_convolution}
 465			\leanok
 466			\uses{def:qld-encoding-pauli-measurement, def:expanded-point-measurement}
 467			The effect at a field value of the evaluated measurement of
 468			Definition~\ref{def:qld-encoding-pauli-measurement} is the sum, over the
 469			pairs of field values adding to that value, of the products of the
 470			evaluated strategy effect and the ideal point projector. This is the
 471			convolution used in the proof of
 472			Equation~\eqref{eq:qld-nonencoding-mass}; it asserts neither an
 473			approximation nor consistency with the strategy's point measurement.
 474		\end{lemma}
 475		\begin{proof}
 476			\leanok
 477			\uses{lem:qld-encoding-pauli-eval}
 478			Expand the relabeled product measurement of
 479			Lemma~\ref{lem:qld-encoding-pauli-eval} at the given field value; the
 480			ancillary factor is the ideal point projector by definition of the
 481			low-degree encoding.
 482		\end{proof}
